"""Generate packages/contracts/tasks.schema.json and tasks.ts from the models of the tasks API (job DR B1). Same scheme as the other contracts (`make contracts`; a test fails if a file is stale)."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.packs.contracts import _ts_type
from app.tasks import models as m

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/tasks/models.py. Do not edit.\n"
    "// Ask Vijaya to do it: plan, approve once, run, report. Every result is simulated until telephony exists.\n"
)
RESPONSES: list[type[BaseModel]] = [m.TaskOut, m.TaskContactsOut, m.TemplatesOut, m.ReportOut]
REQUESTS: list[type[BaseModel]] = [m.PlanIn, m.AnswerIn, m.ExcludeIn, m.ApproveIn, m.CapIn]


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema(
        [(model, "serialization") for model in RESPONSES] + [(model, "validation") for model in REQUESTS], ref_template="#/$defs/{model}"
    )
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "tasks.schema.json",
        "title": "Tasks (job DR B1)",
        "description": "Generated from services/ai-api/app/tasks/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
